package dev.zomboid.tacz;import net.minecraft.client.Minecraft;public class Checks {static int n;static void check(boolean v){n++;if(!v)throw new AssertionError(n);}public static class Event {public String name="crosshair";public boolean canceled;public String getName(){return name;}public Object getGuiGraphics(){return new Object();}public void setCanceled(boolean value){canceled=value;}}public static class Camera {public String fluid="NONE";public String getFluidInCamera(){return fluid;}}public static class FogEvent {public float near=100,far=200;public String type="NONE";public boolean canceled;public String getType(){return type;}public String getMode(){return "FOG_TERRAIN";}public Object getCamera(){return new Object();}public float getNearPlaneDistance(){return near;}public float getFarPlaneDistance(){return far;}public void setNearPlaneDistance(float v){near=v;}public void setFarPlaneDistance(float v){far=v;}public void setCanceled(boolean b){canceled=b;}}public static class Graphics {public int fills;public void fill(int a,int b,int c,int d,int e){fills++;}}public static void main(String[] args){Minecraft mc=Minecraft.M;check(Bridge.thirdPerson());mc.options.view.first=true;check(!Bridge.thirdPerson());Event event=new Event();mc.player.ads=true;check(!Bridge.drawEvent(event)&&!event.canceled);mc.options.view.first=false;check(Bridge.drawEvent(event)&&event.canceled);check(com.tacz.guns.client.event.RenderCrosshairEvent.markers==1);event=new Event();mc.player.ads=false;check(!Bridge.drawEvent(event));event.name="hotbar";mc.player.ads=true;check(!Bridge.drawEvent(event));Graphics graphics=new Graphics();Bridge.draw(graphics,100,100);check(graphics.fills==25);graphics=new Graphics();Bridge.line(graphics,new double[]{0,0},new double[]{300,300});check(graphics.fills>0&&graphics.fills<48);mc.player.gun=false;check(!Bridge.thirdPerson());mc.player=null;check(!Bridge.thirdPerson());check(Weather.cycle(0)==0);check(Weather.cycle(24000)==0);check(Weather.cycle(25200)==1);check(Weather.envelope(30,120)==.5);check(Weather.envelope(60,120)==1);check(Weather.envelope(180,120)==1);check(Weather.envelope(210,120)==.5);check(Weather.envelope(240,120)==0);boolean valid=true;java.util.Set<Integer> holds=new java.util.HashSet<>();for(int i=0;i<1000;i++){int h=Weather.holdSeconds(i);valid&=h>=120&&h<=600;holds.add(h);}check(valid);check(holds.size()>100);check(Weather.cycle(97200)==1);Weather.mode=1;Weather.testHold=120;Weather.testStart=System.nanoTime()-60_000_000_000L;FogEvent fog=new FogEvent();Weather.fog(fog);check(fog.far==12&&fog.near==2&&fog.canceled);fog=new FogEvent();fog.type="WATER";Weather.fog(fog);check(fog.far==200&&!fog.canceled);Weather.mode=-1;fog=new FogEvent();Weather.fog(fog);check(fog.far==200&&!fog.canceled);Weather.mode=1;Weather.testStart=System.nanoTime()-60_000_000_000L;com.cleannrooster.dungeons_iso.mod.Mod.enabled=true;Camera camera=new Camera();Weather.finalFog(camera,"FOG_TERRAIN");check(com.mojang.blaze3d.systems.RenderSystem.end==12&&com.mojang.blaze3d.systems.RenderSystem.start==2);com.mojang.blaze3d.systems.RenderSystem.end=200;camera.fluid="WATER";Weather.finalFog(camera,"FOG_TERRAIN");check(com.mojang.blaze3d.systems.RenderSystem.end==200);camera.fluid="NONE";com.cleannrooster.dungeons_iso.mod.Mod.enabled=false;Weather.finalFog(camera,"FOG_TERRAIN");check(com.mojang.blaze3d.systems.RenderSystem.end==200);System.out.println("Passed "+n+" third-person HUD checks (API doubles)");}}
